 function agendaLogo(e){const name=String(e.event||''),company=Object.keys(agendaLogos).find(key=>key!=='BLS'&&name.toLowerCase().includes(key.toLowerCase()));let key=company;if(!key&&/bls\.gov/.test(e.source||''))key='BLS';if(/Microsoft|微软/i.test(name))return `<span class="mobile-agenda-logo is-brand brand-microsoft" aria-hidden="true"><svg viewBox="0 0 24 24"><path fill="#f25022" d="M1 1h10v10H1z"/><path fill="#7fba00" d="M13 1h10v10H13z"/><path fill="#00a4ef" d="M1 13h10v10H1z"/><path fill="#ffb900" d="M13 13h10v10H13z"/></svg></span>`;if(/Meta/i.test(name))key='Meta';if(/Alphabet|Google/i.test(name))key='Alphabet';if(key){const vectorKey={"Apple":"apple","AMD":"amd","Datadog":"datadog","Palantir":"palantir","Meta":"meta","Alphabet":"google","Tesla":"tesla"}[key];if(vectorKey)return brandIcon(key,brandVectorPaths[vectorKey]);return brandWord(key,({CoreWeave:'CW',Nebius:'N',Arista:'AN',ASML:'ASML',Amazon:'a',BLS:'BLS'})[key]||key.slice(0,3))}let symbol;if(/ISM/.test(name))symbol='<b class="agency-wordmark">ISM</b>';else if(/选举/.test(name))symbol=eventSymbol('<path d="m12 4 10 5-5 9-10-5Z M9 11l2 4 4-1 M5 18l-2 5v6h26v-6l-3-5 M3 23h26 M11 20h10"/>');else if(/地缘|油价|中东/.test(name))symbol=eventSymbol('<circle cx="16" cy="16" r="12"/><path d="M4 16h24 M16 4c-7 6-7 18 0 24 M16 4c7 6 7 18 0 24 M7 9h18 M7 23h18"/>');else symbol=eventSymbol('<path d="m3 11 13-7 13 7H3Z M5 27h22 M3 30h26 M7 14v10 M13 14v10 M19 14v10 M25 14v10"/>');return `<span class="mobile-agenda-logo is-agency" aria-hidden="true">${symbol}</span>`}
 const agendaEvent=e=>{const earnings=/财报|earnings/i.test(e.kind||''),kind=earnings?'earnings':/政策|选举/.test(e.kind||'')?'policy':'macro';const summary=agendaSummary(e);return `<article class="mobile-agenda-event ${kind}${isHigh(e)?' is-important':''}" data-calendar-event-id="${esc(e.id)}" role="button" tabindex="0" aria-expanded="false" aria-label="${esc(e.event+'，'+(e.time||'时间待定')+'，'+summary)}">${dots('calendar:'+e.id)}${agendaLogo(e)}<div class="mobile-agenda-copy"><div class="mobile-agenda-title"><h3>${esc(e.event)}</h3>${P.stars(P.calendarImportance(e))}</div><p title="${esc(summary)}">${esc(summary)}</p></div>${agendaTime(e)}${agendaReturns(e)}</article>`};
 const collapseKey='nasdaq_calendar_collapsed_days_v1';
 let calendarPrefDoc=document;try{if(parent!==window&&parent.location.origin===location.origin)calendarPrefDoc=parent.document}catch{}
 const readCollapsedDays=()=>{try{const value=calendarPrefDoc.cookie.split('; ').find(row=>row.startsWith(collapseKey+'='));const dates=value?JSON.parse(decodeURIComponent(value.slice(collapseKey.length+1))):[];return new Set(Array.isArray(dates)?dates.filter(date=>/^\d{4}-\d{2}-\d{2}$/.test(date)).slice(-120):[])}catch{return new Set()}};
