 root.addEventListener('click',ev=>{const toggle=ev.target.closest('[data-calendar-day-toggle]');if(toggle){const date=toggle.dataset.calendarDayToggle,day=toggle.closest('.mobile-agenda-day'),body=day.querySelector('.mobile-agenda-day-events'),collapse=toggle.getAttribute('aria-expanded')==='true';if(collapse&&selectedCard&&day.contains(selectedCard))closeDetail();animateCalendar(body,!collapse);toggle.setAttribute('aria-expanded',String(!collapse));if(collapse)collapsedDays.add(date);else collapsedDays.delete(date);saveCollapsedDays();return}if(ev.target.closest('[data-calendar-close]')){closeDetail(true);return}const card=ev.target.closest('[data-calendar-event-id]');if(card&&!ev.target.closest('a'))showDetail(card)});
